import {ToolRegistry} from './registry.js';
import {registerLocationTool} from './registryTestSupport.js';

describe('ToolRegistry inputSchema validation', () => {
  it('returns a rejection naming the required property and skips the executor for input missing it', async () => {
    const registry = new ToolRegistry();
    const executorCalls = registerLocationTool(registry);

    const response = await registry.execute('get_weather', {});

    expect({
      executorCalls: executorCalls(),
      namesRequiredLocation: response.result.includes('location') && /required/i.test(response.result),
    }).toEqual({executorCalls: 0, namesRequiredLocation: true});
  });

  it('rejects a wrong-typed property naming the path and expected type without echoing the value', async () => {
    const registry = new ToolRegistry();
    const executorCalls = registerLocationTool(registry);

    const response = await registry.execute('get_weather', {location: 42});

    expect({
      executorCalls: executorCalls(),
      namesPath: response.result.includes('location'),
      namesExpectedType: response.result.includes('string'),
      echoesValue: response.result.includes('42'),
    }).toEqual({executorCalls: 0, namesPath: true, namesExpectedType: true, echoesValue: false});
  });

  it('passes valid input with an unlisted extra property through to the executor unchanged, exactly once', async () => {
    const registry = new ToolRegistry();
    const executorInputs: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}},
      },
      async input => {
        executorInputs.push(input);
        return 'sunny';
      }
    );

    await registry.execute('get_weather', {location: 'Paris', unit: 'celsius'});

    expect(executorInputs).toEqual([{location: 'Paris', unit: 'celsius'}]);
  });

  it('compiles a static schema once at register time and reuses the validator across ten execute calls', async () => {
    const registry = new ToolRegistry();
    let schemaReads = 0;
    const schemaTarget: Record<string, unknown> = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    const inputSchema: Record<string, unknown> = new Proxy(schemaTarget, {
      get: (target, property) => {
        if (typeof property === 'string') schemaReads += 1;
        return Reflect.get(target, property);
      },
    });
    registry.register(
      {name: 'get_weather', description: 'Get weather for a location', inputSchema},
      async () => 'sunny'
    );

    const readsAtRegister = schemaReads;
    let result = '';
    for (let call = 0; call < 10; call++) {
      result = (await registry.execute('get_weather', {location: 'Paris'})).result;
    }

    expect({result, schemaReadsDuringExecutes: schemaReads - readsAtRegister}).toEqual({
      result: 'sunny',
      schemaReadsDuringExecutes: 0,
    });
  });

  it('validates a function-valued definition against the schema it returns for that call, not a stale one', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    let call = 0;
    registry.register(
      () => ({
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema:
          call === 0
            ? {type: 'object', properties: {location: {type: 'string'}}, required: ['location']}
            : {type: 'object', properties: {units: {type: 'string'}}, required: ['units']},
      }),
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const withLocationSchema = await registry.execute('get_weather', {location: 'Paris'});
    call += 1;
    const againstCurrentSchema = await registry.execute('get_weather', {location: 'Paris'});
    call += 1;
    const withUnitsSchema = await registry.execute('get_weather', {units: 'celsius'});

    expect({
      firstResult: withLocationSchema.result,
      secondRejectedForUnits:
        againstCurrentSchema.result.includes('units') && /required/i.test(againstCurrentSchema.result),
      thirdResult: withUnitsSchema.result,
      executorCalls,
    }).toEqual({
      firstResult: 'sunny',
      secondRejectedForUnits: true,
      thirdResult: 'sunny',
      executorCalls: 2,
    });
  });

  it('throws Unknown tool naming the requested name for an unregistered name', async () => {
    const registry = new ToolRegistry();

    const outcome = await registry.execute('no_such_tool', {}).then(
      () => 'resolved',
      (error: Error) => error.message
    );

    expect(outcome).toBe('Unknown tool: no_such_tool');
  });

  it('exposes registrations through has, get, getPromptInstructions and getExamplePrompts', async () => {
    const registry = new ToolRegistry();
    const beforeRegister = {
      hasTool: registry.has('get_weather'),
      lookedUp: registry.get('get_weather'),
      promptInstructions: registry.getPromptInstructions(),
      examplePrompts: registry.getExamplePrompts(),
    };

    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}},
        promptInstructions: 'Call this when the user asks about weather',
        examplePrompts: ['What is the weather in Paris?'],
      },
      async () => 'sunny'
    );
    const tool = registry.get('get_weather');
    const executorResult = await tool?.execute({location: 'Paris'});

    expect(beforeRegister).toEqual({
      hasTool: false,
      lookedUp: undefined,
      promptInstructions: [],
      examplePrompts: [],
    });

    expect({
      hasAfterRegister: registry.has('get_weather'),
      definitionName: tool?.definition.name,
      executorResult,
      promptInstructions: registry.getPromptInstructions(),
      examplePrompts: registry.getExamplePrompts(),
    }).toEqual({
      hasAfterRegister: true,
      definitionName: 'get_weather',
      executorResult: 'sunny',
      promptInstructions: ['get_weather: Call this when the user asks about weather'],
      examplePrompts: ['What is the weather in Paris?'],
    });
  });
});
